"""Robot oil painting. All geometry inferred from RGB/depth cameras; no simulator state access."""
import sys,time,json,os
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot(); self.s=self.r.spec(); o=self.r.get_obs(cameras=[]); self.p=np.array(o.meta['proprio']['now'][7:14]); self.quat=np.array([0,1,0,0.]); self.buf=[]
 def move(self,xyz,t=.5):
  n=max(1,int(np.ceil(t/.05))); dest=np.r_[xyz,self.quat]; start=self.p.copy()
  for i in range(1,n+1): self.buf.append((start+(dest-start)*i/n).tolist())
  self.p=dest
 def flush(self,cams=[]):
  while self.buf:
   a=self.buf[:190]; self.buf=self.buf[190:]
   before=self.r.status()
   try: o=self.r.submit('ee_pose',a,dt=.05,video='none',cameras=cams)
   except Exception:
    status=self.r.wait_ready(); print('RECOVERY',status,flush=True)
    if status['calls']==before['calls']: o=self.r.submit('ee_pose',a,dt=.05,video='none',cameras=cams)
    else: o=self.r.get_obs(cameras=cams)
   with open(OUT+'/motion.jsonl','a') as f:f.write(json.dumps({'actions':a,'meta':o.meta})+'\n')
   if o.stopped or o.done: raise RuntimeError(o.meta)
   failures=[x for x in o.meta.get('plan',[]) if isinstance(x,dict) and x.get('ik_failed')]
   if failures: print('IK failures',failures,flush=True)
  return o
 def obs(self,name):
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save(OUT+'/'+name)
  for c,a in o.last.items():Image.fromarray(a).save(OUT+'/'+name+'_'+c+'.png')
  print('OBS',name,o.meta['time_left_s'],o.meta['proprio']['now'][7:14],flush=True)
 def park(self):
  self.move([self.p[0],self.p[1],.075],.4);self.move([-.30,0,.12],1.6);self.flush()
if __name__=='__main__':
 p=Painter();p.park();p.obs('clear')
